"""Index all saved trial summaries without pooling incompatible experiments."""
from pathlib import Path
import csv,json
from collections import Counter
ROOT=Path(__file__).resolve().parents[1]; out=ROOT/'outputs/comparison_report'
person=json.loads((out/'accepted_trials.json').read_text())
animal=json.loads((ROOT/'outputs/competition/animal_video_manifest.json').read_text())
accepted_person=set(person['accepted_trial_ids']);accepted_animal=set(animal['accepted_trials'])
excluded={x:'Excluded person control: handheld; replaced with fixed-mount controls' for x in person.get('excluded_primary',[])}
excluded.update({x['trial_id']:'Excluded animal-model trial: '+x['reason'] for x in animal.get('excluded_trials',[])})
rows=[]
for path in sorted((ROOT/'outputs').rglob('*.summary.json')):
 s=json.loads(path.read_text());tid=s.get('trial_id',path.stem);g=s.get('ground_truth',{});c=s.get('configuration',{});r=s.get('results',{})
 if tid in accepted_person:group='Person controlled comparison';status='Accepted in person report'
 elif tid in accepted_animal:group='Warmed animal-model comparison';status='Accepted in animal-model report'
 elif 'testing_with_animal_images' in str(path) or tid=='deer_image_test':group='Wildlife still-image development';status='Exploratory; not pooled'
 else:group='Other development / practice';status='Exploratory; not pooled'
 if tid in excluded:status=excluded[tid]
 rows.append(dict(summary_path=str(path.relative_to(ROOT)),trial_id=tid,group=group,status=status,mode=s.get('mode'),lighting=g.get('condition'),target_present=g.get('target_present'),frames=r.get('frames'),detected_frames=r.get('detected_frames'),detection_rate=r.get('detection_rate'),rgb_classes=c.get('rgb_classes'),model=c.get('rgb_model'),world_prompt=c.get('rgb_world_classes'),confidence_threshold=c.get('rgb_confidence'),simulated_radar=c.get('simulated_radar_used'),notes=g.get('notes')))
with (out/'all_trial_inventory.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
counts=Counter(x['group'] for x in rows)
images=[x for x in rows if x['group']=='Wildlife still-image development']
lines=['# WildShield — Overall Experiment Report','','## Scope','','This report indexes all saved trial-summary files under outputs. It links separate experiment families rather than combining incompatible targets, distances, inputs, or software versions into one accuracy figure. Original reports, logs, exclusions, and recordings remain unchanged.','','| Experiment group | Evidence and interpretation |','|---|---|','| Person comparison | 18 accepted physical trials: three present and three absent per lighting condition, at approximately 3 m. |','| Warmed animal-model comparison | 18 accepted physical trials: three present and three absent per lighting condition, at approximately 1 m. |','| Wildlife still-image development | Individual RGB image tests and configuration/debugging runs; no thermal wildlife measurement. |','| Adaptive fusion replay | Reanalysis of the same 18 accepted animal-model trials; no additional physical trials. |','| Other development / practice | Additional summaries indexed for traceability, without post-hoc inclusion in controlled comparisons. |','','## 1. Person trials','','[Original person comparison](comparison_report.md) · [Trial metrics](sensor_performance.csv) · [Inclusion manifest](accepted_trials.json)','','| Lighting, target present | RGB | Thermal | Original AND fusion |','|---|---:|---:|---:|']
with (out/'condition_summary.csv').open() as f:
 for r in csv.DictReader(f):
  if r['target_present']=='True':lines.append('| '+r['condition'].title()+' | '+' | '.join(f"{100*float(r[k]):.1f}%" for k in ['rgb_mean_rate','thermal_mean_rate','fusion_mean_rate'])+' |')
lines+=['','Rates are means of frame-detection percentages across three trials, not population accuracy. All nine accepted empty controls had zero confirmed detections. One handheld dark empty-control was excluded and replaced; some earlier accepted trials were not mounted, which remains a setup confound.','','## 2. Warmed animal-model trials','','[Full report](../competition/animal_video_report.md) · [Trial metrics](../competition/animal_video_results.csv) · [Manifest](../competition/animal_video_manifest.json)','','| Lighting, target present | RGB | Thermal | Original AND fusion |','|---|---:|---:|---:|','| Bright | 100.0% | 90.0% | 90.0% |','| Dim | 75.8% | 90.9% | 69.7% |','| Dark | 0.0% | 90.3% | 0.0% |','','The warmed stuffed-animal surrogate was classified as teddy bear and mapped to animal_model. It was not a live animal. All nine accepted absent controls had zero confirmed detections. Excluded runs: video-animal-dim-absent-01 (residual heat) and video-animal-bright-present-03 (heat-source failure). Originals were preserved.','','## 3. Wildlife still-image development','','Every discovered image-test summary is listed below, including misses and debugging configurations. Repeated names across folders are not assumed to be independent tests. A one-image detection rate of 100% means one processed image was detected, not 100% species accuracy. Entered distance metadata does not establish camera-to-animal distance for a photograph. These tests do not establish audio playback solely from an alert-related filename.','','| Summary path | Frames | Detected | Confidence threshold | Prompt |','|---|---:|---:|---:|---|']
for r in images:lines.append('| ['+r['summary_path']+'](../../'+r['summary_path']+') | '+str(r['frames'])+' | '+str(r['detected_frames'])+' | '+str(r['confidence_threshold'])+' | '+str(r['world_prompt'])+' |')
lines+=['','## 4. Adaptive fusion retrospective replay','','[Replay report](../competition/adaptive_fusion_replay.md) · [Replay table](../competition/adaptive_fusion_replay.csv)','','Adaptive actionable rates on the recorded animal-model positives were 90.0% bright, 90.9% dim, and 90.3% dark; absent controls were 0.0%. These decisions used simulated approaching-radar observations. They illustrate software behavior, not measured radar performance or independently validated animal recognition. Do not add replayed trials to physical-trial counts.','','## 5. Complete inventory','','[All saved trial summaries](all_trial_inventory.csv) includes source paths, group, acceptance/exclusion status, settings and outcomes. Summary-file counts below are inventory counts, not independent experiment counts.','','| Group | Summary files |','|---|---:|']
lines += [f'| {k} | {v} |' for k,v in sorted(counts.items())]
lines+=['','Files with no summary are outside this index. The inventory preserves exploratory runs rather than retrospectively selecting them as controlled evidence.','','## Findings and next steps','','Thermal detection persisted in dark controlled scenes, while requiring both RGB and thermal could suppress detection when RGB failed. Person and animal-model results differ and must remain separate. No combined live-deer thermal validation, physical-radar validation, spatially calibrated fusion, or collision-prevention effectiveness has been demonstrated.','','Next: use fixed mounting consistently, measure illumination, randomize test order, add distractors and distances, spatially calibrate sensors, integrate measured range/motion, and evaluate revised rules on new held-out trials.','','Report assembled with OpenAI Codex assistance; student should verify interpretations and disclose assistance in submission materials.']
(out/'overall_experiment_report.md').write_text('\n'.join(lines)+'\n')
p=out/'comparison_report.md';s=p.read_text();link='[Overall experiment report](overall_experiment_report.md)';
if link not in s:p.write_text(s+'\n## Related experiment groups\n\n'+link+' links the animal-model trials, wildlife-image tests, adaptive replay, and complete trial inventory. This report retains the original 18-person-trial comparison.\n')
assert len(accepted_person)==18 and len(accepted_animal)==18
assert len(rows)==sum(counts.values())
print(json.dumps({'summary_files':len(rows),'groups':dict(counts),'outputs':['overall_experiment_report.md','all_trial_inventory.csv']},indent=2))
